def solve(clue):
    letters, w = clue.split('|')
    n = len(letters)
    base = collections.Counter(letters)
    for p in range(n - len(w) + 1):
        arr = [None] * n
        ok = True
        for i, ch in enumerate(w):
            for q in (p + i, n - 1 - p - i):
                if arr[q] is None:
                    arr[q] = ch
                elif arr[q] != ch:
                    ok = False
        if not ok:
            continue
        c = collections.Counter(base)
        for ch in arr:
            if ch is not None:
                c[ch] -= 1
        if any(v < 0 for v in c.values()):
            continue
        mid = n // 2
        odd = [k for k in c if c[k] % 2]
        if n % 2 and arr[mid] is None:
            if len(odd) != 1:
                continue
            arr[mid] = odd[0]
            c[odd[0]] -= 1
        elif odd:
            continue
        pool = []
        for k in sorted(c):
            pool += [k] * (c[k] // 2)
        pi = 0
        bad = False
        for i in range(n // 2):
            if arr[i] is None:
                if pi >= len(pool):
                    bad = True
                    break
                arr[i] = arr[n - 1 - i] = pool[pi]
                pi += 1
        if bad or None in arr:
            continue
        return ''.join(arr)
    return ''

